pub fn convert_stage(ctx: &Context, node: NodeId) -> Stage {
    let class = match ctx.class_name(node) {
        "f.s" => StageKind::League,
        "f.z" => StageKind::Knockout,
        other => panic!("not a best.L: {other}"),
    };
    let mut value = Stage { class, ..Default::default() };
    match class {
        StageKind::League => {
            value.club_ns = ctx.reference(node, "NS", |ctx, v| ctx.id_of_club_id(v));
            value.country_ref = ctx.reference(node, "RT", |ctx, v| ctx.id_of_country_id(v));
            value.competition = ctx.reference(node, "YY", |ctx, v| ctx.id_of_competition_id(v));
            value.state_league = ctx.reference(node, "YZ", |ctx, v| ctx.id_of_state_league_id(v));
            value.groups = ctx.items(node, "Za", |ctx, v| convert_group(ctx, ctx.node_of(v)));
            value.clubs = ctx.items(node, "Zb", |ctx, v| ctx.id_of_club_id(v));
            value.knockout = ctx.reference(node, "Zc", |ctx, v| ctx.id_of_stage_id(v));
            value.knockout_teams = ctx.int(node, "Zd");
            value.value_ze = ctx.int(node, "Ze");
            value.round = ctx.int(node, "Zf");
            value.phase_code = ctx.int(node, "Zg");
            value.qualify_by_overall_table = ctx.boolean(node, "Zi");
            value.group_count = ctx.int(node, "Zj");
            value.value_zk = ctx.int(node, "Zk");
            value.numbers = ctx.items(node, "as", |ctx, v| ctx.value_int(v));
            value.state_tiebreak = ctx.int(node, "desempateEstadual");
            value.division = ctx.int(node, "divisao");
            value.double_round = ctx.boolean(node, "doisTurnos");
            value.two_legged_rounds = ctx.boolean_array(node, "duasVoltasMataMata");
            value.games_within_group = ctx.boolean(node, "jogosDentroGrupo");
            value.best_third_places = ctx.boolean(node, "melhoresTerceiros");
            value.team_count = ctx.int(node, "nTimes");
            value.name = ctx.string(node, "nome");
            value.division_name = ctx.string(node, "nomeDivisao");
            value.league_name = ctx.string(node, "nomeLiga");
            value.round_count = ctx.int(node, "numeroTurnos");
            value.skip_two_dates = ctx.boolean(node, "pulaDuasDatas");
            value.format_code = ctx.int(node, "var0");
            value.kind = ctx.int(node, "w");
        }
        StageKind::Knockout => {
            value.competition = ctx.reference(node, "YY", |ctx, v| ctx.id_of_competition_id(v));
            value.round = ctx.int(node, "Zf");
            value.phase_code = ctx.int(node, "Zg");
            value.name = ctx.string(node, "nome");
            value.kind = ctx.int(node, "w");
            value.rounds = ctx.items(node, "ZF", |ctx, v| convert_knockout_round(ctx, ctx.node_of(v)));
            value.last_round = ctx.int(node, "ZG");
            value.leg = ctx.int(node, "ZH");
            value.two_legged_knockout_rounds = ctx.boolean_array(node, "ZK");
            value.rounds_computed = ctx.boolean(node, "ZL");
            value.group_stage = ctx.reference(node, "nS", |ctx, v| ctx.id_of_stage_id(v));
            value.competition_kind = ctx.int(node, "tR");
        }
    }
    value
}
